/// <summary>
/// Runs the full four-phase flow for a set of deals, in strict sequence, in the current thread.
/// </summary>
public static void runForDeals(
    container _dealRecIds,
    TAMRebateFromDate _from,
    TAMRebateToDate _to,
    TransDate _transDate,
    boolean _processRebate,
    boolean _processWriteOff)
{
    if (_processRebate)
    {
        METRebateCombinedFlow::createTrans(TAMRebateTransactionType::Rebate, _dealRecIds, _from, _to);
        METRebateCombinedFlow::post(TAMRebateTransactionType::Rebate, _dealRecIds, _from, _to, _transDate);
    }

    if (_processWriteOff)
    {
        // Standard excludes RebateOutputType::Item for non-Rebate types (see controller.updateQueryRebateOutputType).
        container writeOffDeals = METRebateCombinedFlow::filterNonItemOutput(_dealRecIds);
        if (conLen(writeOffDeals) > 0)
        {
            METRebateCombinedFlow::createTrans(TAMRebateTransactionType::WriteOff, writeOffDeals, _from, _to);
            METRebateCombinedFlow::post(TAMRebateTransactionType::WriteOff, writeOffDeals, _from, _to, _transDate);
        }
    }
}

public static void createTrans(
    TAMRebateTransactionType _type,
    container _dealRecIds,
    TAMRebateFromDate _from,
    TAMRebateToDate _to)
{
    TAMRebateCreateTransContract c = TAMRebateCreateTransContract::construct();
    c.parmRebateTransactionType(_type);
    c.parmFromDate(_from);
    c.parmToDate(_to);
    c.parmPackedRecords(_dealRecIds);
    c.parmTableId(tableNum(TAMRebateDeal));

    // Force INLINE execution for this bucket: the contract getter coerces any value <= 0 to 8,
    // so we must explicitly set 1 to keep processRebateTrans's '> 1' guard false and avoid a nested split.
    c.parmMaxBatchTaskNum(1);

    TAMRebateCreateTrans::processRebateTrans(c);
}

/// <summary>
/// Enumerate deal RecIds from the dialog selection query (empty query =&gt; all deals).
/// </summary>
public static container enumerateDealRecIds(str _packedQuery)
{
    Query q;
    container qc = SysOperationHelper::base64Decode(_packedQuery);
    q = qc ? new Query(qc) : new Query(queryStr(METRebateCombinedDeals));

    container recIds;
    QueryRun qr = new QueryRun(q);
    while (qr.next())
    {
        TAMRebateDeal deal = qr.get(tableNum(TAMRebateDeal));
        recIds += deal.RecId;
    }

    return recIds;
}

public static container filterNonItemOutput(container _dealRecIds)
{
    container result;
    for (int i = 1; i <= conLen(_dealRecIds); i++)
    {
        RefRecId dealRecId = conPeek(_dealRecIds, i);
        TAMRebateDeal deal;
        select firstOnly RecId, RebateOutputType from deal
            where deal.RecId == dealRecId
               && deal.RebateOutputType != TAMRebateOutputType::Item;
        if (deal.RecId)
        {
            result += dealRecId;
        }
    }

    return result;
}
